platform.apiLevel = '2.2'
-- Nspire Studio viewer. DOC is generated by the desktop app and inserted below.
--[[DOC]]

local W, H = 318, 212
local TABH, PAD, SBW = 18, 4, 3
local cur, scroll = 1, {}
local layout, contentH = {}, {}
local focus = nil          -- {tab, element index}
local images = {}
local results = {}         -- output/graph cache, cleared when inputs change
local dirty = true

----------------------------------------------------------------- helpers
local function rgb(c, d)
  c = c or d or 0
  return math.floor(c / 65536) % 256, math.floor(c / 256) % 256, c % 256
end

local function setc(gc, c, d) gc:setColorRGB(rgb(c, d)) end

local B64 = {}
do
  local s = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
  for i = 1, 64 do B64[s:byte(i)] = i - 1 end
end

local function b64dec(s)
  local out, n = {}, 0
  local bytes = {}
  for i = 1, #s - 3, 4 do
    local a, b, c, d = B64[s:byte(i)], B64[s:byte(i + 1)], B64[s:byte(i + 2)], B64[s:byte(i + 3)]
    local v = a * 262144 + b * 4096 + (c or 0) * 64 + (d or 0)
    n = n + 1; bytes[n] = math.floor(v / 65536) % 256
    if c then n = n + 1; bytes[n] = math.floor(v / 256) % 256 end
    if d then n = n + 1; bytes[n] = v % 256 end
  end
  return bytes, n
end

-- Image payload: TI.Image header (20 bytes raw) + PackBits on 16-bit pixels.
-- control byte k < 128: k+1 literal pixels follow; k >= 128: next pixel repeated k-126 times.
local function decodeImage(e)
  local bytes, n = b64dec(e.data)
  local parts, np = {}, 0
  local chunk, nc = {}, 0
  local function put(lo, hi)
    nc = nc + 1; chunk[nc] = string.char(lo, hi)
    if nc >= 512 then np = np + 1; parts[np] = table.concat(chunk); chunk = {}; nc = 0 end
  end
  local hdr = {}
  for i = 1, 20 do hdr[i] = string.char(bytes[i]) end
  np = 1; parts[1] = table.concat(hdr)
  local i = 21
  while i <= n do
    local k = bytes[i]; i = i + 1
    if k < 128 then
      for _ = 0, k do put(bytes[i], bytes[i + 1]); i = i + 2 end
    else
      local lo, hi = bytes[i], bytes[i + 1]; i = i + 2
      for _ = 1, k - 126 do put(lo, hi) end
    end
  end
  if nc > 0 then np = np + 1; parts[np] = table.concat(chunk) end
  local ok, img = pcall(image.new, table.concat(parts))
  if ok then return img end
  return false
end

local function getImage(key, e)
  if images[key] == nil then images[key] = decodeImage(e) end
  return images[key]
end

local function font(gc, style, size)
  gc:setFont("sansserif", style or "r", size or 10)
end

-- Word wrap; honours explicit newlines.
local function wrap(gc, text, maxw)
  local lines = {}
  for para in (text .. "\n"):gmatch("(.-)\n") do
    local line = ""
    for word in para:gmatch("%S+") do
      local try = line == "" and word or (line .. " " .. word)
      if gc:getStringWidth(try) <= maxw then
        line = try
      else
        if line ~= "" then lines[#lines + 1] = line end
        -- break very long words
        while gc:getStringWidth(word) > maxw and #word > 1 do
          local k = #word
          while k > 1 and gc:getStringWidth(word:sub(1, k)) > maxw do k = k - 1 end
          lines[#lines + 1] = word:sub(1, k)
          word = word:sub(k + 1)
        end
        line = word
      end
    end
    lines[#lines + 1] = line
  end
  return lines
end

----------------------------------------------------------------- math
local function inputs()
  local cons = {}
  for _, tab in ipairs(DOC.tabs) do
    for _, e in ipairs(tab.items) do
      if e.t == "in" and e.var ~= "" and e.value ~= nil and e.value ~= "" then
        cons[#cons + 1] = e.var .. "=(" .. e.value .. ")"
      end
    end
  end
  return cons
end

local function clean(s)
  if s == nil then return nil end
  s = tostring(s)
  s = s:gsub("\226\136\146", "-")       -- U+2212 minus
  return s
end

local function evalWith(expr, cons)
  local full = expr
  if #cons > 0 then full = "(" .. expr .. ")|" .. table.concat(cons, " and ") end
  local ok, res, err = pcall(math.evalStr, full)
  if not ok then return nil, "error" end
  if res == nil then return nil, tostring(err or "error") end
  return res
end

local function toNum(s)
  if not s then return nil end
  s = clean(s)
  s = s:gsub("\225\180\135", "e")        -- U+1D07 small capital E
  return tonumber(s)
end

local function recompute()
  results = {}
  local cons = inputs()
  -- outputs evaluate in document order; a named output feeds later ones
  for ti, tab in ipairs(DOC.tabs) do
    for ei, e in ipairs(tab.items) do
      if e.t == "out" then
        local expr = e.expr
        if not e.exact then expr = "approx(" .. expr .. ")" end
        if e.digits and e.digits >= 0 and not e.exact then
          expr = "round(" .. expr .. "," .. e.digits .. ")"
        end
        local res, err = evalWith(expr, cons)
        results[ti .. ":" .. ei] = res and clean(res) or ("? " .. (err or ""))
        if res and e.var and e.var ~= "" then
          cons[#cons + 1] = e.var .. "=(" .. res .. ")"
        end
      end
    end
  end
  results.cons = cons
  dirty = false
end

local function graphData(key, e)
  if results[key] then return results[key] end
  local cons = results.cons or inputs()
  local data = {}
  local n = e.samples or 120
  local step = (e.xmax - e.xmin) / n
  for fi, f in ipairs(e.fns) do
    local list = evalWith("seq(approx(" .. f.expr .. "),x," .. e.xmin .. "," .. e.xmax .. "," .. step .. ")", cons)
    local pts = {}
    if list then
      local k = 0
      for item in clean(list):gsub("[{}]", ""):gmatch("[^,]+") do
        pts[k] = toNum(item); k = k + 1
      end
    end
    data[fi] = { pts = pts, n = n }
  end
  results[key] = data
  return data
end

----------------------------------------------------------------- layout
local function measure(gc, tabi)
  local items = DOC.tabs[tabi].items
  local y = PAD
  local cw = W - 2 * PAD - SBW
  local L = {}
  for i, e in ipairs(items) do
    local h = 0
    local entry = { y = y }
    if e.t == "h" or e.t == "p" then
      font(gc, e.t == "h" and "b" or e.style, e.size)
      entry.lines = wrap(gc, e.text or "", cw)
      entry.lh = gc:getStringHeight("Ag")
      h = #entry.lines * entry.lh
      if e.t == "h" then h = h + 2 end
    elseif e.t == "img" or e.t == "eq" then
      h = e.h
    elseif e.t == "graph" then
      h = e.h
    elseif e.t == "in" or e.t == "out" then
      font(gc, "r", 10)
      h = gc:getStringHeight("Ag") + 4
    elseif e.t == "hr" then
      h = 5
    elseif e.t == "sp" then
      h = e.h or 8
    end
    entry.h = h
    L[i] = entry
    y = y + h + (e.t == "sp" and 0 or 3)
  end
  layout[tabi] = L
  contentH[tabi] = y + PAD
end

local function viewH() return H - TABH end

local function maxScroll(t) return math.max(0, (contentH[t] or 0) - viewH()) end

local function clampScroll()
  scroll[cur] = math.max(0, math.min(scroll[cur] or 0, maxScroll(cur)))
end

----------------------------------------------------------------- drawing
local function drawTabs(gc)
  local bg = DOC.theme.tabbg
  setc(gc, bg); gc:fillRect(0, 0, W, TABH)
  font(gc, "b", 9)
  local n = #DOC.tabs
  local x = 0
  local tw = math.floor(W / n)
  for i, tab in ipairs(DOC.tabs) do
    local w = (i == n) and (W - x) or tw
    if i == cur then
      setc(gc, DOC.theme.bg); gc:fillRect(x, 2, w, TABH - 2)
      setc(gc, DOC.theme.accent); gc:fillRect(x, 0, w, 2)
      setc(gc, DOC.theme.fg)
    else
      setc(gc, DOC.theme.tabfg)
    end
    local name = tab.name
    while #name > 1 and gc:getStringWidth(name) > w - 4 do name = name:sub(1, -2) end
    gc:drawString(name, x + (w - gc:getStringWidth(name)) / 2, 2, "top")
    if i > 1 then setc(gc, DOC.theme.tabfg); gc:drawLine(x, 4, x, TABH - 4) end
    x = x + w
  end
end

local function niceStep(span)
  local p = 10 ^ math.floor(math.log10(span / 5))
  for _, m in ipairs({ 1, 2, 5, 10 }) do
    if span / (m * p) <= 6 then return m * p end
  end
  return 10 * p
end

local function fmtNum(v)
  if math.abs(v) < 1e-12 then return "0" end
  local s = string.format("%.4g", v)
  return s
end

local function drawGraph(gc, key, e, x, y, w, h)
  setc(gc, 0xFFFFFF); gc:fillRect(x, y, w, h)
  local data = graphData(key, e)
  local ymin, ymax = e.ymin, e.ymax
  local gy = e.gy or 1
  if e.yauto then
    local lo, hi
    for _, d in ipairs(data) do
      for k = 0, d.n do
        local v = d.pts[k]
        if v and v == v and v > -1e300 and v < 1e300 then
          lo = lo and math.min(lo, v) or v
          hi = hi and math.max(hi, v) or v
        end
      end
    end
    if lo then
      if hi - lo < 1e-12 * math.max(1, math.abs(hi)) then lo, hi = lo - 1, hi + 1 end
      local pad = (hi - lo) * 0.08
      ymin, ymax = lo - pad, hi + pad
      gy = niceStep(ymax - ymin)
    end
  end
  local function sx(v) return x + (v - e.xmin) / (e.xmax - e.xmin) * (w - 1) end
  local function sy(v) return y + h - 1 - (v - ymin) / (ymax - ymin) * (h - 1) end
  gc:clipRect("set", x, y, w, h)
  if e.grid then
    setc(gc, 0xE4E4E4)
    local gx = e.gx or 1
    if (e.xmax - e.xmin) / gx < 60 then
      for v = math.ceil(e.xmin / gx) * gx, e.xmax, gx do gc:drawLine(sx(v), y, sx(v), y + h) end
    end
    if (ymax - ymin) / gy < 60 then
      for v = math.ceil(ymin / gy) * gy, ymax, gy do gc:drawLine(x, sy(v), x + w, sy(v)) end
    end
  end
  setc(gc, 0x707070)
  if ymin <= 0 and ymax >= 0 then gc:drawLine(x, sy(0), x + w, sy(0)) end
  if e.xmin <= 0 and e.xmax >= 0 then gc:drawLine(sx(0), y, sx(0), y + h) end
  for fi, f in ipairs(e.fns) do
    setc(gc, f.color, 0x1060D0)
    gc:setPen("medium", "smooth")
    local d = data[fi]
    local step = (e.xmax - e.xmin) / d.n
    local px, py
    for k = 0, d.n do
      local v = d.pts[k]
      if v and v == v and v > ymin - 10 * (ymax - ymin) and v < ymax + 10 * (ymax - ymin) then
        local X, Y = sx(e.xmin + k * step), sy(v)
        if px then gc:drawLine(px, py, X, Y) end
        px, py = X, Y
      else
        px = nil
      end
    end
  end
  gc:setPen("thin", "smooth")
  gc:clipRect("reset")
  setc(gc, 0xB0B0B0); gc:drawRect(x, y, w - 1, h - 1)
  font(gc, "r", 7); setc(gc, 0x707070)
  gc:drawString(fmtNum(ymax), x + 2, y + 1, "top")
  gc:drawString(fmtNum(ymin), x + 2, y + h - 1, "bottom")
  local s = fmtNum(e.xmax)
  gc:drawString(s, x + w - 2 - gc:getStringWidth(s), y + h - 1, "bottom")
end

local function drawField(gc, e, x, y, w, h, value, focused, isOut)
  font(gc, "r", 10)
  setc(gc, DOC.theme.fg)
  local label = (e.label or "") .. (e.label ~= "" and ":" or "")
  gc:drawString(label, x, y + 2, "top")
  local lw = math.max(gc:getStringWidth(label) + 6, e.lw or 0)
  local unit = e.unit or ""
  local uw = unit ~= "" and (gc:getStringWidth(unit) + 4) or 0
  local bx, bw = x + lw, w - lw - uw
  if isOut then
    setc(gc, 0xEEF3FA); gc:fillRect(bx, y, bw, h)
    setc(gc, 0xB8C8DC); gc:drawRect(bx, y, bw, h - 1)
    font(gc, "b", 10); setc(gc, DOC.theme.fg)
  else
    setc(gc, 0xFFFFFF); gc:fillRect(bx, y, bw, h)
    if focused then setc(gc, DOC.theme.accent) else setc(gc, 0x909090) end
    gc:drawRect(bx, y, bw, h - 1)
    if focused then gc:drawRect(bx + 1, y + 1, bw - 2, h - 3) end
    setc(gc, DOC.theme.fg)
  end
  local v = value or ""
  while #v > 1 and gc:getStringWidth(v) > bw - 6 do v = v:sub(2) end
  gc:drawString(v, bx + 3, y + 2, "top")
  if focused then
    local cx = bx + 3 + gc:getStringWidth(v)
    gc:drawLine(cx, y + 3, cx, y + h - 4)
  end
  if unit ~= "" then
    font(gc, "r", 10); setc(gc, DOC.theme.fg)
    gc:drawString(unit, bx + bw + 4, y + 2, "top")
  end
end

function on.paint(gc)
  W, H = platform.window:width(), platform.window:height()
  if dirty then recompute() end
  if not layout[cur] then measure(gc, cur) end
  clampScroll()
  setc(gc, DOC.theme.bg); gc:fillRect(0, 0, W, H)
  local items = DOC.tabs[cur].items
  local L = layout[cur]
  local off = TABH - scroll[cur]
  local cw = W - 2 * PAD - SBW
  gc:clipRect("set", 0, TABH, W, H - TABH)
  for i, e in ipairs(items) do
    local en = L[i]
    local y = en.y + off
    if y + en.h >= TABH and y <= H then
      local key = cur .. ":" .. i
      if e.t == "h" or e.t == "p" then
        font(gc, e.t == "h" and "b" or e.style, e.size)
        setc(gc, e.color, DOC.theme.fg)
        for li, line in ipairs(en.lines) do
          local x = PAD
          if e.align == "center" then x = PAD + (cw - gc:getStringWidth(line)) / 2
          elseif e.align == "right" then x = PAD + cw - gc:getStringWidth(line) end
          gc:drawString(line, x, y + (li - 1) * en.lh, "top")
        end
        if e.t == "h" then
          setc(gc, DOC.theme.accent)
          gc:fillRect(PAD, y + en.h - 2, cw, 1)
        end
      elseif e.t == "img" or e.t == "eq" then
        local img = getImage(key, e)
        local x = PAD
        if e.align == "center" then x = PAD + (cw - e.w) / 2
        elseif e.align == "right" then x = PAD + cw - e.w end
        if img then
          gc:drawImage(img, x, y)
        else
          setc(gc, 0x909090); gc:drawRect(x, y, e.w - 1, e.h - 1)
          font(gc, "r", 7); gc:drawString("image unsupported", x + 2, y + 2, "top")
        end
      elseif e.t == "graph" then
        drawGraph(gc, key, e, PAD, y, cw, e.h)
      elseif e.t == "in" then
        local f = focus and focus[1] == cur and focus[2] == i
        drawField(gc, e, PAD, y, cw, en.h, e.value, f, false)
      elseif e.t == "out" then
        drawField(gc, e, PAD, y, cw, en.h, results[key] or "", false, true)
      elseif e.t == "hr" then
        setc(gc, 0xC0C0C0); gc:fillRect(PAD, y + 2, cw, 1)
      end
    end
  end
  gc:clipRect("reset")
  -- scrollbar
  local ms = maxScroll(cur)
  if ms > 0 then
    local vh = viewH()
    local bh = math.max(12, vh * vh / contentH[cur])
    local by = TABH + (vh - bh) * scroll[cur] / ms
    setc(gc, 0xE0E0E0); gc:fillRect(W - SBW, TABH, SBW, vh)
    setc(gc, 0x8A8A8A); gc:fillRect(W - SBW, by, SBW, bh)
  end
  drawTabs(gc)
end

----------------------------------------------------------------- input
local function refresh() platform.window:invalidate() end

local function inputList(t)
  local l = {}
  for i, e in ipairs(DOC.tabs[t].items) do if e.t == "in" then l[#l + 1] = i end end
  return l
end

local function ensureVisible()
  if not focus or not layout[cur] then return end
  local en = layout[cur][focus[2]]
  if not en then return end
  local s = scroll[cur] or 0
  if en.y < s then s = en.y - PAD end
  if en.y + en.h > s + viewH() then s = en.y + en.h - viewH() + PAD end
  scroll[cur] = s
end

local function selectTab(t)
  if t < 1 or t > #DOC.tabs then return end
  cur = t
  local l = inputList(cur)
  focus = l[1] and { cur, l[1] } or nil
  refresh()
end

local function moveFocus(dir)
  local l = inputList(cur)
  if #l == 0 then return false end
  local idx = 0
  if focus and focus[1] == cur then
    for k, v in ipairs(l) do if v == focus[2] then idx = k end end
  end
  idx = idx + dir
  if idx < 1 then idx = #l elseif idx > #l then idx = 1 end
  focus = { cur, l[idx] }
  ensureVisible()
  refresh()
  return true
end

local function focused()
  if focus and focus[1] == cur then return DOC.tabs[cur].items[focus[2]] end
end

local function changed()
  dirty = true
  results = {}
  refresh()
end

function on.arrowLeft() selectTab(cur > 1 and cur - 1 or #DOC.tabs) end
function on.arrowRight() selectTab(cur < #DOC.tabs and cur + 1 or 1) end
function on.arrowUp() scroll[cur] = (scroll[cur] or 0) - 20; refresh() end
function on.arrowDown() scroll[cur] = (scroll[cur] or 0) + 20; refresh() end
function on.tabKey() moveFocus(1) end
function on.backtabKey() moveFocus(-1) end
function on.enterKey() if not moveFocus(1) then changed() end end

function on.charIn(ch)
  local e = focused()
  if not e then return end
  if ch == "\226\136\146" then ch = "-" end
  e.value = (e.value or "") .. ch
  changed()
end

function on.backspaceKey()
  local e = focused()
  if not e or not e.value or e.value == "" then return end
  -- remove one UTF-8 character
  local v = e.value
  local k = #v
  while k > 1 and v:byte(k) >= 128 and v:byte(k) < 192 do k = k - 1 end
  e.value = v:sub(1, k - 1)
  changed()
end

function on.clearKey()
  local e = focused()
  if e then e.value = ""; changed() end
end

function on.mouseDown(x, y)
  if y < TABH then
    selectTab(math.min(#DOC.tabs, math.floor(x / (W / #DOC.tabs)) + 1))
    return
  end
  if not layout[cur] then return end
  local cy = y - TABH + (scroll[cur] or 0)
  for i, en in ipairs(layout[cur]) do
    if cy >= en.y and cy < en.y + en.h and DOC.tabs[cur].items[i].t == "in" then
      focus = { cur, i }; refresh(); return
    end
  end
end

function on.resize(w, h)
  W, H = w, h
  layout, contentH = {}, {}
  refresh()
end

function on.save()
  local vals = {}
  for ti, tab in ipairs(DOC.tabs) do
    for ei, e in ipairs(tab.items) do
      if e.t == "in" then vals[ti .. ":" .. ei .. ":" .. e.var] = e.value end
    end
  end
  return { v = vals, id = DOC.id, tab = cur }
end

function on.restore(state)
  if type(state) ~= "table" or state.id ~= DOC.id then return end
  for ti, tab in ipairs(DOC.tabs) do
    for ei, e in ipairs(tab.items) do
      local v = state.v and state.v[ti .. ":" .. ei .. ":" .. (e.var or "")]
      if e.t == "in" and v ~= nil then e.value = v end
    end
  end
  if state.tab and DOC.tabs[state.tab] then cur = state.tab end
  dirty = true
end

if DOC.angle == "deg" then
  pcall(math.setEvalSettings, { { "Angle", "Degree" } })
end
for i = 1, #DOC.tabs do scroll[i] = 0 end
selectTab(1)
